<script setup lang="ts">import{computed,ref}from'vue';import{useI18n}from'vue-i18n';import AccountShell from'../components/AccountShell.vue';const{t,tm}=useI18n(),active=ref(0);const counts=[12,2,3,5,2];const rows=[{id:'SH-20260802-001',status:3,address:'Alex R. · 12*** Market St, CA',cards:'3',coin:'2,450',carrier:'UPS · 1Z47****',node:'eta'},{id:'SH-20260725-023',status:2,address:'Alex R. · 8*** Pine Ave, NY',cards:'5',coin:'3,800',carrier:'pendingCarrier',node:'packing'},{id:'SH-20260712-112',status:4,address:'Alex R. · 9*** Ocean Rd, HI',cards:'2',coin:'5,500',carrier:'USPS · 94****',node:'deliveredAt'}];const statuses=computed(()=>tm('shipping.statuses') as string[]),headers=computed(()=>tm('shipping.headers') as string[]),filtered=computed(()=>active.value===0?rows:rows.filter(row=>row.status===active.value));const value=(key:string)=>['pendingCarrier','packing','eta','deliveredAt'].includes(key)?t(`shipping.${key}`):key</script>
<template><AccountShell><div><span class="eyebrow">{{t('eyebrow.shipping')}}</span><h1>{{t('shipping.title')}}</h1><p class="muted">{{t('shipping.subtitle')}}</p></div><div class="status-grid"><button v-for="(status,index) in statuses" :key="status" :class="['card',{active:active===index}]" @click="active=index"><span>{{status}}</span><b>{{counts[index]}}</b></button></div><section class="card shipping"><div class="shipping-head"><div><h2>{{t('shipping.my')}}</h2><p>{{t('shipping.count',{count:filtered.length})}}</p></div><input class="input" :placeholder="t('shipping.search')"></div><div class="table-wrap"><table class="table"><thead><tr><th v-for="header in headers" :key="header">{{header}}</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td :data-label="headers[0]"><b>{{row.id}}</b><small>2026-08-02 14:22</small></td><td :data-label="headers[1]"><span :class="['pill',row.status===4?'green':row.status===3?'gold':'']">{{statuses[row.status]}}</span></td><td :data-label="headers[2]">{{row.address}}</td><td :data-label="headers[3]">{{t('common.cards',{count:row.cards})}}<br><b>{{row.coin}} Coin</b></td><td :data-label="headers[4]">{{value(row.carrier)}}</td><td :data-label="headers[5]">{{value(row.node)}}</td><td :data-label="headers[6]"><button class="link">{{t('common.details')}}</button></td></tr></tbody></table></div></section></AccountShell></template>
<style scoped>h1{margin-bottom:5px}.status-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:25px 0}.status-grid button{padding:18px;text-align:left;border:1px solid var(--line);background:white}.status-grid button span{display:block;font-size:12px;color:var(--muted)}.status-grid button b{display:block;font-size:27px;margin-top:6px}.status-grid button.active{border-color:var(--gold);box-shadow:inset 0 -4px var(--gold)}.shipping{padding:22px}.shipping-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.shipping-head h2{margin:0}.shipping-head p{margin:4px 0;color:var(--muted);font-size:12px}.shipping-head .input{width:260px}.table small{display:block;color:var(--muted)}.link{border:0;background:transparent;color:var(--brown);font-weight:700}@media(max-width:767px){.status-grid{grid-template-columns:repeat(5,120px);overflow:auto;padding-bottom:6px}.shipping{padding:12px}.shipping-head{display:grid;gap:10px}.shipping-head .input{width:100%}}</style>
